import pathlib,shutil,subprocess,os,json,concurrent.futures,hashlib
root=pathlib.Path.cwd();p=root/'var/posting-sync-collection-20261025';s=json.loads((p/'setup.json').read_text());changed=list(s['source_sha256'])
for v in ['candidate','candidate-diag']:
 for f in changed:shutil.copy2(root/f,p/(v+'-source')/f)
def build(v):
 ctx=p/(v+'-image');src=p/(v+'-source');image=s['candidate_images'][v]['image']
 with (p/(v+'-final-build.log')).open('w') as log:
  subprocess.run(['go','build','-trimpath','-ldflags=-s -w','-o',str(ctx/'oimobbs'),'./cmd/oimobbs'],cwd=src,env=dict(os.environ,CGO_ENABLED='0'),stdout=log,stderr=subprocess.STDOUT,check=True)
  subprocess.run(['docker','build','--network=none','-t',image,str(ctx)],stdout=log,stderr=subprocess.STDOUT,check=True)
 return v,{'image':image,'id':subprocess.check_output(['docker','image','inspect',image,'--format','{{.Id}}'],text=True).strip()}
