"""保存同期の収集候補を同じ制約で比較し、失敗と再起動照合も残す。"""
import json,pathlib,subprocess,time,sys,shutil
p=pathlib.Path(__file__).resolve().parent;root=p.parents[1];setup=json.loads((p/'setup.json').read_text())
images={'final-candidate':setup['candidate_images']['candidate'],'final-candidate-diag':setup['candidate_images']['candidate-diag'],'baseline':setup['images']['after'],'candidate':setup['candidate_images']['candidate'],'baseline-diag':setup['images']['after-diag'],'candidate-diag':setup['candidate_images']['candidate-diag']}
for f in ['balanced120-probe.py','balanced120_capacity.py']:
 if not (p/f).exists():shutil.copy2(root/'var/textcodec-posting-20261025'/f,p/f)
base=['mise','exec','--','python3',str(p/'balanced120-probe.py'),'--memory','4g','--egress-bps','80000000','--waf','--waf-posting-rate','100000','--waf-posting-concurrent','256','--waf-posting-client-rate','1000','--optional-log-stats','--collect-server-log','--posting-capacity-rate','1600','--posting-capacity-seconds','5','--posting-capacity-workers','120','--posting-capacity-threads','16','--posting-capacity-fixed-count']
rows=json.loads((p/'trials.json').read_text()) if (p/'trials.json').exists() else []
def run(v,cpu,rep,kind='fixed'):
 name=f'{kind}-{v}-r{rep}-{cpu}cpu';dest=p/(name+'.json')
 if any(r['name']==name for r in rows):return
 if dest.exists():raise RuntimeError('unregistered existing output '+name)
 cmd=base+['--image',images[v]['id'],'--cpus',str(cpu),'--output',str(dest)]
 if kind in ['mixed','mixed-diag']:
  cmd.remove('--posting-capacity-fixed-count')
  for flag,value in [('--posting-capacity-rate','160'),('--posting-capacity-seconds','20' if kind=='mixed-diag' else '60'),('--egress-bps','8000000000')]:cmd[cmd.index(flag)+1]=value
  cmd+=['--posting-capacity-reads','400','--posting-capacity-subject-every','4']
  if kind=='mixed':cmd+=['--posting-capacity-restart']
 if v.endswith('diag'):cmd+=['--collect-profiles']
 (p/'status.json').write_text(json.dumps({'stage':name,'completed':rows},indent=2));print('START',name,flush=True)
 started=time.monotonic()
 with (p/(name+'.log')).open('w') as f:r=subprocess.run(cmd,cwd=root,stdout=f,stderr=subprocess.STDOUT)
 row={'name':name,'version':v,'cpus':cpu,'rep':rep,'kind':kind,'exit_code':r.returncode,'command':cmd,'wall_s':time.monotonic()-started}
 if dest.exists():
  s=json.loads(dest.read_text());d=s['duration_with_drain_seconds'];n=s['summary']['success']
  row.update({'throughput':n/d,'cpu_ms_per_success':s['resources']['cpu_cores_average']*d*1000/max(n,1),'summary':s['summary'],'read_summary':s['read_summary'],'integrity':s['integrity']['ok'],'recovery':s['recovery'],'resources':s['resources'],'memory_peak_bytes':s['memory_peak_bytes']})
 rows.append(row);(p/'trials.json').write_text(json.dumps(rows,indent=2));print('DONE',name,json.dumps({k:row.get(k) for k in ['exit_code','throughput','cpu_ms_per_success','summary']}),flush=True)
 if r.returncode or not row.get('integrity') or row['resources']['oom_kill_delta'] or row['recovery']['success']!=100:raise RuntimeError('integrity/OOM/recovery failure '+name)
 if kind in ['fixed','fixed-diag','final-fixed','final-fixed-diag'] and (row['summary']['errors'] or row['summary']['skipped']):raise RuntimeError('fixed-work acceptance failure '+name)
mode=sys.argv[1] if len(sys.argv)>1 else 'screen'
if mode=='screen':
 for v in ['baseline','candidate']:run(v,4,1,'mixed')
 for cpu,versions in [(2,['baseline','candidate']),(4,['candidate','baseline'])]:
  for v in versions:run(v,cpu,1)
elif mode=='repeat':
 for v in ['candidate','baseline']:run(v,4,2,'mixed')
 for cpu,versions in [(2,['candidate','baseline']),(4,['baseline','candidate']),(1,['baseline','candidate'])]:
  for v in versions:run(v,cpu,2 if cpu!=1 else 1)
elif mode=='final':
 for cpu,versions in [(2,['baseline','final-candidate']),(4,['final-candidate','baseline'])]:
  for v in versions:run(v,cpu,1,'final-fixed')
elif mode=='final-diagnostic':
 run('final-candidate-diag',2,1,'final-fixed-diag')
elif mode=='extra':
 cpu=int(sys.argv[2]);rep=int(sys.argv[3])
 for v in ['baseline','candidate']:run(v,cpu,rep)
elif mode=='fixed-diagnostic':
 for v in ['baseline-diag','candidate-diag']:run(v,2,1,'fixed-diag')
elif mode=='diagnostic':
 for v in ['baseline-diag','candidate-diag']:run(v,4,1,'mixed-diag')
else:raise RuntimeError('unknown mode')
(p/'status.json').write_text(json.dumps({'stage':'complete','completed':rows},indent=2));print('RUNS COMPLETE',flush=True)
